const N = {{n}};
let sum = 0;
for (let i = 0; i < N; i++) sum += 0.1;
const want = N * 0.1;
ctx.fillStyle = '#eee'; ctx.font = '15px ui-monospace, monospace';
ctx.fillText('0.1 을 ' + N + '번 더하면', 16, 34);
ctx.fillStyle = '#f87171'; ctx.fillText(sum.toFixed(12), 16, 64);
ctx.fillStyle = '#9ca3af'; ctx.font = '13px ui-monospace, monospace';
ctx.fillText('기대값 ' + want.toFixed(12), 16, 92);
ctx.fillStyle = sum === want ? '#4ade80' : '#fbbf24';
ctx.fillText('차이 ' + Math.abs(sum - want).toExponential(3), 16, 118);
ctx.fillText('=== 로 같나? ' + (sum === want), 16, 144);

