if (a === b) …

// ✅ 허용 오차를 정한다
const 가깝다 = (a, b, eps = 1e-9) => Math.abs(a - b) < eps;

// 값이 아주 클 때는 상대 오차로
const 가깝다2 = (a, b, eps = 1e-9) =>
  Math.abs(a - b) <= eps * Math.max(1, Math.abs(a), Math.abs(b));
